import{_ as p,a0 as s,w as e,s as u,I as l,x as i,a1 as n,A as o,ao as k}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const K=JSON.parse('{"title":"由 KRACK 攻擊想到的確保網絡安全的小貼士 | LCTT x X-CMD","titleTemplate":false,"description":"由 KRACK 攻擊想到的確保網絡安全的小貼士 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"由 KRACK 攻擊想到的確保網絡安全的小貼士 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"由 KRACK 攻擊想到的確保網絡安全的小貼士 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171018 Tips to Secure Your Network in the Wake of KRACK","title":"由 KRACK 攻擊想到的確保網絡安全的小貼士","tag":"201711","desc":""},"relativePath":"201711/20171018 Tips to Secure Your Network in the Wake of KRACK.md","filePath":"[post].md"}'),d={name:"201711/20171018 Tips to Secure Your Network in the Wake of KRACK.md"};function T(a,t,w,m,f,g){const r=s("Link");return e(),u("div",null,[t[42]||(t[42]=l("h1",{id:"由-krack-攻擊想到的確保網絡安全的小貼士",tabindex:"-1"},[i("由 KRACK 攻擊想到的確保網絡安全的小貼士 "),l("a",{class:"header-anchor",href:"#由-krack-攻擊想到的確保網絡安全的小貼士","aria-label":"Permalink to “由 KRACK 攻擊想到的確保網絡安全的小貼士”"},"​")],-1)),t[43]||(t[43]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/krack-security.jpg?itok=_gKsJm7N",alt:"KRACK",title:"KRACK"})],-1)),t[44]||(t[44]=l("blockquote",null,[l("p",null,"最近的 KRACK （密鑰重裝攻擊，這是一個安全漏洞名稱或該漏洞利用攻擊行為的名稱）漏洞攻擊的目標是位於你的設備和 Wi-Fi 訪問點之間的鏈路，這個訪問點或許是在你家裏、辦公室中、或你喜歡的咖啡吧中的任何一台路由器。這些提示能幫你提升你的連接的安全性。")],-1)),l("p",null,[n(r,{href:"https://www.krackattacks.com/"},{default:o(()=>[...t[0]||(t[0]=[i("KRACK 漏洞攻擊",-1)])]),_:1}),t[2]||(t[2]=i(" 出現已經一段時間了，並且已經在 ",-1)),n(r,{href:"https://blog.cryptographyengineering.com/2017/10/16/falling-through-the-kracks/"},{default:o(()=>[...t[1]||(t[1]=[i("相關技術網站",-1)])]),_:1}),t[3]||(t[3]=i(" 上有很多詳細的討論，因此，我將不在這裏重複攻擊的技術細節。攻擊方式的總結如下：",-1))]),t[45]||(t[45]=k('<ul><li>在 WPA2 無線握手協議中的一個缺陷允許攻擊者在你的設備和 wi-fi 訪問點之間嗅探或操縱通訊。</li><li>這個問題在 Linux 和 Android 設備上尤其嚴重，由於在 WPA2 標準中的措辭含糊不清，也或許是在實現它時的錯誤理解，事實上，在底層的操作系統打完補丁以前，該漏洞一直可以強制無線流量以無加密方式通訊。</li><li>還好這個漏洞可以在客户端上修補，因此，天並沒有塌下來，而且，WPA2 加密標準並沒有像 WEP 標準那樣被淘汰（不要通過切換到 WEP 加密的方式去“修復”這個問題）。</li><li>大多數流行的 Linux 發行版都已經通過升級修復了這個客户端上的漏洞，因此，老老實實地去更新它吧。</li><li>Android 也很快修復了這個漏洞。如果你的設備在接收 Android 安全補丁，你會很快修復這個漏洞。如果你的設備不再接收這些更新，那麼，這個特別的漏洞將是你停止使用你的舊設備的一個理由。</li></ul><p>即使如此，從我的觀點來看， Wi-Fi 是不可信任的基礎設施鏈中的另一個環節，並且，我們應該完全避免將其視為可信任的通信通道。</p><h3 id="wi-fi-是不受信任的基礎設備" tabindex="-1">Wi-Fi 是不受信任的基礎設備 <a class="header-anchor" href="#wi-fi-是不受信任的基礎設備" aria-label="Permalink to “Wi-Fi 是不受信任的基礎設備”">​</a></h3><p>如果從你的筆記本電腦或移動設備中讀到這篇文章，那麼，你的通信鏈路看起來應該是這樣：</p><p><img src="https://lh4.googleusercontent.com/ihouLL-yQ-ZZCKpp3MvLH6-iWC3cMlxNqN6YySOqa6cIR9ShSHIwjR04KAXnkU9TO7vMZ27QEz1QjA0j0MrECcEZSpJoA4uURwHZjec4TSQpgd7-982isvpx89C73N9wt1cEzq9l" alt="Blank Network Diagram - Basics.png"></p><p>KRACK 攻擊目標是在你的設備和 Wi-Fi 訪問點之間的鏈接，訪問點或許是在你家裏、辦公室中、或你喜歡的咖啡吧中的任何一台路由器。</p><p><img src="https://lh3.googleusercontent.com/xvW0IhutTplAB3VHO00lSMLcJNK31DfjTCxEB8_0PkcenM9P46y0K-w8WZjVWQapj2pU9a8mRmG57sVhwv8kVn6lghoTnv8qkz8FRbo2VBCk_gK8M2ipi20di1qDTdj_dPGyRqWi" alt="Blank Network Diagram - Where Kracks happen (1).png"></p><p>實際上，這個圖示應該看起來像這樣：</p><p><img src="https://lh4.googleusercontent.com/e4InTHN5ql28nw21NM8cz3HwO1VMZN4-itSArWqH2_6m492ZZKu851uD4pn0Ms3kfHEc2Rst1_c8ENIsoFJ-mEkhFjMH7zUbg9r0t0la78cPnLls_iaVeBwmf5vjS9XWpUIgHScS" alt="Blank Network Diagram - Everywhere (1).png"></p><p>Wi-Fi 僅僅是在我們所不應該信任的信道上的長長的通信鏈的第一個鏈路。讓我來猜猜，你使用的 Wi-Fi 路由器或許從開始使用的第一天氣就沒有得到過一個安全更新，並且，更糟糕的是，它或許使用了一個從未被更改過的、缺省的、易猜出的管理憑據（用户名和密碼）。除非你自己安裝並配置你的路由器，並且你能記得你上次更新的它的固件的時間，否則，你應該假設現在它已經被一些人控制並不能信任的。</p><p>在 Wi-Fi 路由器之後，我們的通訊進入一般意義上的常見不信任區域 —— 這要根據你的猜疑水平。這裏有上游的 ISP 和接入提供商，其中的很多已經被指認監視、更改、分析和銷售我們的流量數據，試圖從我們的瀏覽習慣中掙更多的錢。通常他們的安全補丁計劃辜負了我們的期望，最終讓我們的流量暴露在一些惡意者眼中。</p><p>一般來説，在互聯網上，我們還必須擔心強大的國家級的參與者能夠操縱核心網絡協議，以執行大規模的網絡監視和狀態級的流量過濾。</p><h3 id="https-協議" tabindex="-1">HTTPS 協議 <a class="header-anchor" href="#https-協議" aria-label="Permalink to “HTTPS 協議”">​</a></h3><p>值的慶幸的是，我們有一個基於不信任的介質進行安全通訊的解決方案，並且，我們可以每天都能使用它 —— 這就是 HTTPS 協議，它加密你的點對點的互聯網通訊，並且確保我們可以信任站點與我們之間的通訊。</p>',14)),l("p",null,[t[5]||(t[5]=i("Linux 基金會的一些措施，比如像 ",-1)),n(r,{href:"https://letsencrypt.org/"},{default:o(()=>[...t[4]||(t[4]=[i("Let’s Encrypt",-1)])]),_:1}),t[6]||(t[6]=i(" 使世界各地的網站所有者都可以很容易地提供端到端的加密，這有助於確保我們的個人設備與我們試圖訪問的網站之間的任何有安全隱患的設備不再是個問題。",-1))]),t[46]||(t[46]=l("p",null,[l("img",{src:"https://lh6.googleusercontent.com/aFzS-eiJCJpTTQD967NzKZOfFcS0rQ8rTW4L_aiKQ3Q3pTkkeqGjBBAdYASw38VMxKLbNOwbKpGOT9CGzI1XVmyzeiuGqI9YSdkBjBwwJZ0Ee2k8EZonl43HeAv4o6hk2YKonbtW",alt:"Blank Network Diagram - HTTPS (1).png"})],-1)),t[47]||(t[47]=l("p",null,"是的... 基本沒關係。",-1)),t[48]||(t[48]=l("h3",{id:"dns-——-剩下的一個問題",tabindex:"-1"},[i("DNS —— 剩下的一個問題 "),l("a",{class:"header-anchor",href:"#dns-——-剩下的一個問題","aria-label":"Permalink to “DNS —— 剩下的一個問題”"},"​")],-1)),l("p",null,[t[8]||(t[8]=i("雖然，我們可以儘量使用 HTTPS 去創建一個可信的通信信道，但是，這裏仍然有一個攻擊者可以訪問我們的路由器或修改我們的 Wi-Fi 流量的機會 —— 在使用 KRACK 的這個案例中 —— 可以欺騙我們的通訊進入一個錯誤的網站。他們可以利用我們仍然非常依賴 DNS 的這一事實 —— 這是一個未加密的、易受欺騙的 ",-1)),n(r,{href:"https://en.wikipedia.org/wiki/Domain_Name_System#History"},{default:o(()=>[...t[7]||(t[7]=[i("誕生自上世紀 80 年代的協議",-1)])]),_:1}),t[9]||(t[9]=i("。",-1))]),t[49]||(t[49]=l("p",null,[l("img",{src:"https://lh4.googleusercontent.com/EZfhN4crHvLX2cn3wbukh9z7aYsaB073jHMqI5IbOHba4VPhsc2GHMud75D9B_T6K2-ry6zXu_54jDa16gc0G3OC-RP7crchc0ltNGZPhoHpTsc_T6T0XXtMofUYw_iqlW5bG_0g",alt:"Blank Network Diagram - LOL DNS.png"})],-1)),t[50]||(t[50]=l("p",null,"DNS 是一個將像 “linux.com” 這樣人類友好的域名，轉換成計算機可以用於和其它計算機通訊的 IP 地址的一個系統。要轉換一個域名到一個 IP 地址，計算機將會查詢解析器軟件 —— 它通常運行在 Wi-Fi 路由器或一個系統上。解析器軟件將查詢一個分佈式的“根”域名服務器網絡，去找到在互聯網上哪個系統有 “linux.com” 域名所對應的 IP 地址的“權威”信息。",-1)),l("p",null,[t[11]||(t[11]=i("麻煩就在於，所有發生的這些通訊都是未經認證的、",-1)),n(r,{href:"https://en.wikipedia.org/wiki/DNS_spoofing"},{default:o(()=>[...t[10]||(t[10]=[i("易於欺騙的",-1)])]),_:1}),t[12]||(t[12]=i("、明文協議、並且響應可以很容易地被攻擊者修改，去返回一個不正確的數據。如果有人去欺騙一個 DNS 查詢並且返回錯誤的 IP 地址，他們可以操縱我們的系統最終發送 HTTP 請求到那裏。",-1))]),l("p",null,[t[14]||(t[14]=i("幸運的是，HTTPS 有一些內置的保護措施去確保它不會很容易地被其它人誘導至其它假冒站點。惡意服務器上的 TLS 憑據必須與你請求的 DNS 名字匹配 —— 並且它必須由一個你的瀏覽器認可的信譽良好的 ",-1)),n(r,{href:"https://en.wikipedia.org/wiki/Certificate_authority"},{default:o(()=>[...t[13]||(t[13]=[i("認證機構（CA）",-1)])]),_:1}),t[15]||(t[15]=i(" 所簽發。如果不是這種情況，你的瀏覽器將在你試圖去與他們告訴你的地址進行通訊時出現一個很大的警告。如果你看到這樣的警告，在選擇不理會警告之前，請你格外小心，因為，它有可能會把你的秘密泄露給那些可能會對付你的人。",-1))]),l("p",null,[t[19]||(t[19]=i("如果攻擊者完全控制了路由器，他們可以在一開始時，通過攔截來自服務器指示你建立一個安全連接的響應，以阻止你使用 HTTPS 連接（這被稱為 “",-1)),n(r,{href:"https://en.wikipedia.org/wiki/Moxie_Marlinspike#Notable_research"},{default:o(()=>[...t[16]||(t[16]=[i("SSL 脱衣攻擊",-1)])]),_:1}),t[20]||(t[20]=i("”）。 為了幫助你防護這種類型的攻擊，網站可以增加一個 ",-1)),n(r,{href:"https://en.wikipedia.org/wiki/HTTP_Strict_Transport_Security"},{default:o(()=>[...t[17]||(t[17]=[i("特殊響應頭（HSTS）",-1)])]),_:1}),t[21]||(t[21]=i(" 去告訴你的瀏覽器以後與它通訊時總是使用 HTTPS 協議，但是，這僅僅是在你首次訪問之後的事。對於一些非常流行的站點，瀏覽器現在包含一個 ",-1)),n(r,{href:"https://hstspreload.org/"},{default:o(()=>[...t[18]||(t[18]=[i("硬編碼的域名列表",-1)])]),_:1}),t[22]||(t[22]=i("，即使是首次連接，它也將總是使用 HTTPS 協議訪問。",-1))]),l("p",null,[t[24]||(t[24]=i("現在已經有了 DNS 欺騙的解決方案，它被稱為 ",-1)),n(r,{href:"https://en.wikipedia.org/wiki/Domain_Name_System_Security_Extensions"},{default:o(()=>[...t[23]||(t[23]=[i("DNSSEC",-1)])]),_:1}),t[25]||(t[25]=i("，由於有重大的障礙 —— 真實和可感知的（LCTT 譯註，指的是要求實名認證），它看起來接受程度很慢。在 DNSSEC 被普遍使用之前，我們必須假設，我們接收到的 DNS 信息是不能完全信任的。",-1))]),t[51]||(t[51]=l("h3",{id:"使用-vpn-去解決-最後一公里-的安全問題",tabindex:"-1"},[i("使用 VPN 去解決“最後一公里”的安全問題 "),l("a",{class:"header-anchor",href:"#使用-vpn-去解決-最後一公里-的安全問題","aria-label":"Permalink to “使用 VPN 去解決“最後一公里”的安全問題”"},"​")],-1)),t[52]||(t[52]=l("p",null,"因此，如果你不能信任固件太舊的 Wi-Fi 和/或無線路由器，我們能做些什麼來確保發生在你的設備與常説的互聯網之間的“最後一公里”通訊的完整性呢？",-1)),t[53]||(t[53]=l("p",null,"一個可接受的解決方案是去使用信譽好的 VPN 供應商的服務，它將在你的系統和他們的基礎設施之間建立一條安全的通訊鏈路。這裏有一個期望，就是它比你的路由器提供者和你的當前互聯網供應商更注重安全，因為，他們處於一個更好的位置去確保你的流量不會受到惡意的攻擊或欺騙。在你的工作站和移動設備之間使用 VPN，可以確保免受像 KRACK 這樣的漏洞攻擊，不安全的路由器不會影響你與外界通訊的完整性。",-1)),t[54]||(t[54]=l("p",null,[l("img",{src:"https://lh4.googleusercontent.com/vdulGCwUB239d76QXgtV3AcC0fG0YEi_LWCzOAYAEhFlEExtXXSOyXB-aq4PAI652egsUcgAXNi1KfUNWnUewWBlHkyRHSBDb5jWpD11MrSsfjbkTRZGTVhRv6wOszNdTQ12TKG8",alt:"Blank Network Diagram - VPN.png"})],-1)),l("p",null,[t[27]||(t[27]=i("這有一個很重要的警告是，當你選擇一個 VPN 供應商時，你必須確信他們的信用；否則，你將被一撥惡意的人出賣給其它人。遠離任何人提供的所謂“免費 VPN”，因為，它們可以通過監視你和向市場營銷公司銷售你的流量來賺錢。 ",-1)),n(r,{href:"https://www.vpnmentor.com/bestvpns/overall/"},{default:o(()=>[...t[26]||(t[26]=[i("這個網站",-1)])]),_:1}),t[28]||(t[28]=i(" 是一個很好的資源，你可以去比較他們提供的各種 VPN，去看他們是怎麼互相競爭的。",-1))]),t[55]||(t[55]=l("p",null,"注意，你所有的設備都應該在它上面安裝 VPN，那些你每天使用的網站，你的私人信息，尤其是任何與你的錢和你的身份（政府、銀行網站、社交網絡、等等）有關的東西都必須得到保護。VPN 並不是對付所有網絡級漏洞的萬能藥，但是，當你在機場使用無法保證的 Wi-Fi 時，或者下次發現類似 KRACK 的漏洞時，它肯定會保護你。",-1)),t[56]||(t[56]=l("hr",null,null,-1)),l("p",null,[t[30]||(t[30]=i("via: ",-1)),n(r,{href:"https://www.linux.com/blog/2017/10/tips-secure-your-network-wake-krack"},{default:o(()=>[...t[29]||(t[29]=[i("https://www.linux.com/blog/2017/10/tips-secure-your-network-wake-krack",-1)])]),_:1})]),l("p",null,[t[34]||(t[34]=i("作者：",-1)),n(r,{href:"https://www.linux.com/users/mricon"},{default:o(()=>[...t[31]||(t[31]=[i("KONSTANTIN RYABITSEV",-1)])]),_:1}),t[35]||(t[35]=i(" 譯者：",-1)),n(r,{href:"https://github.com/qhwdw"},{default:o(()=>[...t[32]||(t[32]=[i("qhwdw",-1)])]),_:1}),t[36]||(t[36]=i(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[33]||(t[33]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[39]||(t[39]=i("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[37]||(t[37]=[i("LCTT",-1)])]),_:1}),t[40]||(t[40]=i(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...t[38]||(t[38]=[i("Linux中國",-1)])]),_:1}),t[41]||(t[41]=i(" 榮譽推出",-1))])])}const C=p(d,[["render",T]]);export{K as __pageData,C as default};
